const rupiah=value=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(value);
const escapeHtml=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
let profile=null,addresses=[],accountOrders=[],authMode='login';
const authView=document.querySelector('#authView'),dashboard=document.querySelector('#dashboard'),authForm=document.querySelector('#authForm'),notice=document.querySelector('.notice');
notice.textContent='Akun, alamat, dan riwayat pesanan tersimpan aman di RuangRupa.';
const authTitle=authView.querySelector('h1'),authMeta=authView.querySelector('.meta'),nameField=document.querySelector('#authName').closest('.field'),phoneField=document.querySelector('#authPhone').closest('.field'),passwordField=document.createElement('div'),modeSwitch=document.createElement('div');
passwordField.className='field';passwordField.innerHTML='<label for="authPassword">Kata sandi</label><input id="authPassword" type="password" minlength="8" maxlength="128" autocomplete="current-password" required placeholder="Minimal 8 karakter">';
authForm.querySelector('.btn').before(passwordField);modeSwitch.className='auth-switch';modeSwitch.innerHTML='<button type="button" data-auth-mode="login" class="active">Masuk</button><button type="button" data-auth-mode="register">Daftar</button>';authForm.before(modeSwitch);const postalField=document.createElement('div');postalField.className='field';postalField.innerHTML='<label for="addressPostal">Kode pos</label><input id="addressPostal" required inputmode="numeric" pattern="[0-9]{5}" maxlength="5">';document.querySelector('#addressCity').closest('.field').after(postalField);const securityButton=document.createElement('button');securityButton.type='button';securityButton.dataset.tab='security';securityButton.textContent='Keamanan';document.querySelector('.menu').append(securityButton);const securityTab=document.createElement('section');securityTab.className='card tab';securityTab.id='tab-security';securityTab.hidden=true;securityTab.innerHTML='<h2>Keamanan akun</h2><p class="meta">Mengganti kata sandi akan mengeluarkan akun dari perangkat lain.</p><form id="passwordForm"><div class="field"><label for="currentPassword">Kata sandi saat ini</label><input id="currentPassword" type="password" autocomplete="current-password" required></div><div class="profile-grid"><div class="field"><label for="newPassword">Kata sandi baru</label><input id="newPassword" type="password" autocomplete="new-password" minlength="8" maxlength="128" required placeholder="Minimal 8 karakter"></div><div class="field"><label for="confirmPassword">Ulangi kata sandi baru</label><input id="confirmPassword" type="password" autocomplete="new-password" minlength="8" maxlength="128" required></div></div><button class="btn" type="submit" style="margin-top:18px">Ganti kata sandi</button><p class="message" id="passwordMessage" aria-live="polite"></p></form>';document.querySelector('.content').append(securityTab);
const forgotButton=document.createElement('button');forgotButton.type='button';forgotButton.className='forgot-link';forgotButton.textContent='Lupa kata sandi?';authForm.append(forgotButton);const resetToken=new URLSearchParams(location.search).get('reset'),resetView=document.createElement('section');resetView.className='auth';resetView.hidden=true;resetView.innerHTML='<h1>Pulihkan akun</h1><p class="meta">Masukkan email untuk menerima tautan pemulihan.</p><form id="resetRequestForm"><div class="field"><label for="resetEmail">Email</label><input id="resetEmail" type="email" autocomplete="email" required></div><button class="btn" type="submit">Kirim tautan pemulihan</button><p class="message" id="resetRequestMessage" aria-live="polite"></p></form><form id="resetConfirmForm" hidden><div class="field"><label for="resetPassword">Kata sandi baru</label><input id="resetPassword" type="password" autocomplete="new-password" minlength="8" maxlength="128" required></div><div class="field"><label for="resetPasswordConfirm">Ulangi kata sandi baru</label><input id="resetPasswordConfirm" type="password" autocomplete="new-password" minlength="8" maxlength="128" required></div><button class="btn" type="submit">Simpan kata sandi baru</button><p class="message" id="resetConfirmMessage" aria-live="polite"></p></form><button class="forgot-link" id="backToLogin" type="button">Kembali ke halaman masuk</button>';authView.after(resetView);const style=document.createElement('style');style.textContent='.auth-switch{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:22px 0 8px}.auth-switch button{border:1px solid var(--line);border-radius:999px;padding:10px;background:white;font-weight:700}.auth-switch button.active{background:var(--forest);color:white;border-color:var(--forest)}.message{min-height:1.4em;margin:12px 0 0;color:var(--rust);font-size:.86rem}.forgot-link{display:block;border:0;background:transparent;color:var(--rust);padding:10px 0;cursor:pointer;margin:4px auto 0}@media(max-width:760px){.menu{grid-template-columns:repeat(2,1fr)}}';document.head.append(style);const message=document.createElement('p');message.className='message';authForm.append(message);
async function api(path,options={}){const response=await fetch(path,{...options,headers:{'content-type':'application/json',...(options.headers||{})}}),data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'Layanan akun belum tersedia');return data}
function setAuthMode(mode){authMode=mode;const register=mode==='register';authTitle.textContent=register?'Buat akun pelanggan':'Masuk ke akun';authMeta.textContent=register?'Daftar untuk menyimpan profil pelanggan.':'Gunakan email dan kata sandi Anda.';nameField.hidden=!register;phoneField.hidden=!register;nameField.querySelector('input').required=register;phoneField.querySelector('input').required=register;document.querySelector('#authPassword').autocomplete=register?'new-password':'current-password';authForm.querySelector('.btn').textContent=register?'Daftar':'Masuk';forgotButton.hidden=register;message.textContent='';document.querySelectorAll('[data-auth-mode]').forEach(button=>button.classList.toggle('active',button.dataset.authMode===mode))}
function saveProfileLocal(){if(profile)localStorage.setItem('ruangrupa-profile',JSON.stringify(profile));else localStorage.removeItem('ruangrupa-profile')}
function showAccount(){authView.hidden=!!profile;dashboard.hidden=!profile;if(!profile)return;document.querySelector('#sideName').textContent=profile.name;document.querySelector('#sideEmail').textContent=profile.email;document.querySelector('#avatar').textContent=profile.name.split(/\s+/).slice(0,2).map(part=>part[0]).join('').toUpperCase();document.querySelector('#profileName').value=profile.name;document.querySelector('#profileEmail').value=profile.email;document.querySelector('#profileEmail').readOnly=true;document.querySelector('#profilePhone').value=profile.phone;loadAddresses();loadOrders()}
authForm.addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;button.textContent=authMode==='register'?'Mendaftarkan…':'Memeriksa…';message.textContent='';try{const data=await api('/api/customer/session',{method:'POST',body:JSON.stringify({mode:authMode,name:document.querySelector('#authName').value.trim(),email:document.querySelector('#authEmail').value.trim(),phone:document.querySelector('#authPhone').value.trim(),password:document.querySelector('#authPassword').value})});profile=data.customer;saveProfileLocal();showAccount()}catch(error){message.textContent=error.message}finally{button.disabled=false;button.textContent=authMode==='register'?'Daftar':'Masuk'}});
function showReset(){authView.hidden=true;dashboard.hidden=true;resetView.hidden=false;document.querySelector('#resetRequestForm').hidden=!!resetToken;document.querySelector('#resetConfirmForm').hidden=!resetToken;resetView.querySelector('.meta').textContent=resetToken?'Buat kata sandi baru untuk akun Anda.':'Masukkan email untuk menerima tautan pemulihan.'}
forgotButton.addEventListener('click',showReset);document.querySelector('#backToLogin').addEventListener('click',()=>{history.replaceState({},'',location.pathname);resetView.hidden=true;authView.hidden=false;setAuthMode('login')});document.querySelector('#resetRequestForm').addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter,message=document.querySelector('#resetRequestMessage');button.disabled=true;button.textContent='Mengirim…';message.textContent='';try{const data=await api('/api/customer/password-reset/request',{method:'POST',body:JSON.stringify({email:document.querySelector('#resetEmail').value.trim()})});message.style.color='#376446';message.textContent=data.message}catch(error){message.style.color='var(--rust)';message.textContent=error.message}finally{button.disabled=false;button.textContent='Kirim tautan pemulihan'}});document.querySelector('#resetConfirmForm').addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter,message=document.querySelector('#resetConfirmMessage'),newPassword=document.querySelector('#resetPassword').value,confirmPassword=document.querySelector('#resetPasswordConfirm').value;button.disabled=true;button.textContent='Menyimpan…';message.textContent='';try{const data=await api('/api/customer/password-reset/confirm',{method:'POST',body:JSON.stringify({token:resetToken,newPassword,confirmPassword})});message.style.color='#376446';message.textContent=data.message;setTimeout(()=>{location.href='account.html'},1400)}catch(error){message.style.color='var(--rust)';message.textContent=error.message}finally{button.disabled=false;button.textContent='Simpan kata sandi baru'}});
document.querySelectorAll('[data-auth-mode]').forEach(button=>button.addEventListener('click',()=>setAuthMode(button.dataset.authMode)));
document.querySelector('#profileForm').addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;button.textContent='Menyimpan…';try{const data=await api('/api/customer/profile',{method:'PATCH',body:JSON.stringify({name:document.querySelector('#profileName').value.trim(),phone:document.querySelector('#profilePhone').value.trim()})});profile=data.customer;saveProfileLocal();showAccount();notice.textContent='Profil berhasil disimpan di RuangRupa.'}catch(error){notice.textContent=error.message}finally{button.disabled=false;button.textContent='Simpan profil'}});
document.querySelector('#addressForm').addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;button.textContent='Menyimpan…';try{await api('/api/customer/addresses',{method:'POST',body:JSON.stringify({label:document.querySelector('#addressLabel').value.trim(),city:document.querySelector('#addressCity').value.trim(),postalCode:document.querySelector('#addressPostal').value.trim(),text:document.querySelector('#addressText').value.trim()})});event.target.reset();await loadAddresses()}catch(error){notice.textContent=error.message}finally{button.disabled=false;button.textContent='Tambah alamat'}});
async function loadAddresses(){const list=document.querySelector('#addressList');list.innerHTML='<div class="empty">Memuat alamat…</div>';try{const data=await api('/api/customer/addresses');addresses=data.addresses;localStorage.setItem('ruangrupa-addresses',JSON.stringify(addresses));renderAddresses()}catch(error){list.innerHTML=`<div class="empty">${escapeHtml(error.message)}</div>`}}
function renderAddresses(){const list=document.querySelector('#addressList');list.innerHTML=addresses.length?addresses.map(address=>`<article class="address"><div><strong>${escapeHtml(address.label)}</strong><p>${escapeHtml(address.text)}</p><p class="meta">${escapeHtml(address.city)} · ${escapeHtml(address.postalCode)}</p></div><button class="small-btn danger" data-remove-address="${address.id}">Hapus</button></article>`).join(''):'<div class="empty">Belum ada alamat tersimpan.</div>';list.querySelectorAll('[data-remove-address]').forEach(button=>button.addEventListener('click',async()=>{button.disabled=true;try{await api(`/api/customer/addresses/${button.dataset.removeAddress}`,{method:'DELETE'});await loadAddresses()}catch(error){notice.textContent=error.message;button.disabled=false}}))}
async function loadOrders(){const list=document.querySelector('#orderList');list.innerHTML='<div class="empty">Memuat pesanan…</div>';try{const data=await api('/api/customer/orders');accountOrders=data.orders;const localOrders=JSON.parse(localStorage.getItem('ruangrupa-orders')||'[]');accountOrders.forEach(order=>{const existing=localOrders.find(item=>item.id===order.id);if(existing){existing.paymentToken=order.trackingToken;existing.status=order.status}else localOrders.push({...order,paymentToken:order.trackingToken,items:[]})});localStorage.setItem('ruangrupa-orders',JSON.stringify(localOrders));renderOrders()}catch(error){list.innerHTML=`<div class="empty">${escapeHtml(error.message)}</div>`}}
function renderOrders(){const list=document.querySelector('#orderList');list.innerHTML=accountOrders.length?accountOrders.map(order=>`<article class="order"><div><span class="pill ${escapeHtml(order.status)}">${order.status==='paid'?'Berhasil':order.status==='failed'?'Gagal':'Menunggu'}</span><p><strong>${escapeHtml(order.id)}</strong></p><p class="meta">${new Date(order.createdAt.endsWith?.('Z')?order.createdAt:`${order.createdAt}Z`).toLocaleString('id-ID')} · ${rupiah(order.total)}</p><p class="meta">Pengiriman: ${escapeHtml({waiting:'Menunggu',preparing:'Disiapkan',shipped:'Dikirim',completed:'Selesai'}[order.fulfillmentStatus]||'Menunggu')}</p></div><a class="small-btn" href="track.html?order=${encodeURIComponent(order.id)}">Lacak pesanan</a></article>`).join(''):'<div class="empty">Belum ada pesanan yang terhubung ke akun ini.</div>'}
document.querySelector('#passwordForm').addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter,message=document.querySelector('#passwordMessage'),currentPassword=document.querySelector('#currentPassword').value,newPassword=document.querySelector('#newPassword').value,confirmPassword=document.querySelector('#confirmPassword').value;message.textContent='';if(newPassword!==confirmPassword){message.textContent='Konfirmasi kata sandi belum sama';return}button.disabled=true;button.textContent='Menyimpan…';try{await api('/api/customer/password',{method:'PATCH',body:JSON.stringify({currentPassword,newPassword,confirmPassword})});event.target.reset();message.style.color='#376446';message.textContent='Kata sandi berhasil diganti. Sesi di perangkat lain sudah dihentikan.'}catch(error){message.style.color='var(--rust)';message.textContent=error.message}finally{button.disabled=false;button.textContent='Ganti kata sandi'}});
document.querySelectorAll('[data-tab]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-tab]').forEach(item=>item.classList.toggle('active',item===button));document.querySelectorAll('.tab').forEach(tab=>tab.hidden=tab.id!==`tab-${button.dataset.tab}`)}));
document.querySelector('#logout').textContent='Keluar';document.querySelector('#logout').addEventListener('click',async()=>{await fetch('/api/customer/session',{method:'DELETE'});profile=null;saveProfileLocal();showAccount();setAuthMode('login')});
(async()=>{setAuthMode('login');if(resetToken){showReset();return}try{const data=await api('/api/customer/session');if(data.authenticated){profile=data.customer;saveProfileLocal()}else profile=null}catch{profile=null}showAccount()})();
